"use strict";
// The export is a function that also has methods: calling it answers
// another such function for the named palette. Each one is built by a class
// whose constructor keeps the function on `this` while it attaches the
// methods, and then answers the function instead of the instance.
const swatches = (name) => {
  const made = {};
  made.dark = () => name + "-900";
  made.light = (step) => name + "-" + (step || 100);
  made.both = () => [made.dark(), made.light()];
  return made;
};

class Palette {
  constructor(options = { name: null, steps: 9 }) {
    const again = function (next = { name: null, steps: 9 }) {
      return new Palette(next);
    };
    this.pick = again;
    if (typeof options !== "object" || options === null) {
      options = { name: options, steps: 9 };
    }
    const name = options.name || "slate";
    const steps = options.steps || 9;
    this.pick.label = () => name;
    this.pick.steps = () => steps;
    const extension = swatches(name);
    Object.keys(extension).forEach((key) => {
      this.pick[key] = extension[key];
    });
    return this.pick;
  }
}

module.exports = new Palette();
